// Parse RSS XML and extract items
const xml = $input.first().json.data;

// Simple XML parsing for RSS items
const items = [];
const itemMatches = xml.match(/<item>([\s\S]*?)<\/item>/g);

if (itemMatches) {
  for (const item of itemMatches) {
    const title = (item.match(/<title><\!\[CDATA\[([\s\S]*?)\]\]><\/title>/) || item.match(/<title>([\s\S]*?)<\/title>/) || [])[1] || '';
    const link = (item.match(/<link>([\s\S]*?)<\/link>/) || [])[1] || '';
    const description = (item.match(/<description><\!\[CDATA\[([\s\S]*?)\]\]><\/description>/) || item.match(/<description>([\s\S]*?)<\/description>/) || [])[1] || '';
    const pubDate = (item.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || [])[1] || '';

    items.push({
      json: {
        title: title.trim(),
        link: link.trim(),
        content: description.trim(),
        pubDate: pubDate.trim()
      }
    });
  }
}

return items.length > 0 ? items : [{ json: { title: '', link: '', content: '', pubDate: '', empty: true } }];

