// Extract AI response and format as CSV Result string
const aiResponse = $input.first().json;
const rssItem = $('Parse RSS Items').first().json;

let resultText = '';
try {
  const content = aiResponse.choices[0].message.content;
  resultText = content.replace(/\n/g, ' | ').trim();
} catch (e) {
  resultText = '1. موضوع: متفرقه | 2. اولویت: Low | 3. اقدام: نیاز به بررسی | 4. محله: نامشخص';
}

return [{
  json: {
    Title: rssItem.title || 'بدون عنوان',
    Source: rssItem.link || 'https://t.me/khozkhabar',
    Content: rssItem.content || '',
    Result: resultText
  }
}];
